import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.DecompInterface;
import ghidra.app.decompiler.DecompileResults;
import ghidra.app.decompiler.DecompiledFunction;
import ghidra.program.model.listing.Function;
import ghidra.program.model.listing.FunctionManager;
import ghidra.program.model.address.Address;

import java.io.File;
import java.io.FileWriter;
import java.io.BufferedWriter;
import java.io.PrintWriter;

public class ExportDecompiledC extends GhidraScript {

    @Override
    public void run() throws Exception {
        String[] args = getScriptArgs();
        String outDirPath = (args != null && args.length > 0)
                ? args[0]
                : System.getProperty("user.dir");

        File outDir = new File(outDirPath);
        if (!outDir.exists() && !outDir.mkdirs()) {
            printerr("Cannot create output dir: " + outDirPath);
            return;
        }

        DecompInterface ifc = new DecompInterface();
        ifc.toggleCCode(true);
        ifc.toggleSyntaxTree(false);
        if (!ifc.openProgram(currentProgram)) {
            printerr("Decompiler failed to open program");
            return;
        }

        File cFile = new File(outDir, "all_functions.c");
        File csvFile = new File(outDir, "functions.csv");

        BufferedWriter cw = new BufferedWriter(new FileWriter(cFile));
        PrintWriter csv = new PrintWriter(new BufferedWriter(new FileWriter(csvFile)));

        cw.write("// Auto-generated by ExportDecompiledC.java\n");
        cw.write("// Program: " + currentProgram.getName() + "\n");
        cw.write("// ImageBase: " + currentProgram.getImageBase() + "\n\n");
        csv.println("entry,name,size,numParams,isThunk,decompiled");

        FunctionManager fm = currentProgram.getFunctionManager();
        int total = 0;
        int ok = 0;

        for (Function f : fm.getFunctions(true)) {
            if (monitor.isCancelled()) {
                break;
            }
            total++;
            Address entry = f.getEntryPoint();
            boolean decompiled = false;
            try {
                DecompileResults res = ifc.decompileFunction(f, 90, monitor);
                if (res != null && res.decompileCompleted()) {
                    DecompiledFunction df = res.getDecompiledFunction();
                    if (df != null) {
                        cw.write("//===== " + f.getName() + " @ " + entry + " =====\n");
                        cw.write(df.getC());
                        cw.write("\n\n");
                        decompiled = true;
                        ok++;
                    }
                }
            } catch (Exception e) {
                cw.write("//===== " + f.getName() + " @ " + entry + " ===== [DECOMPILE ERROR: "
                        + e.getMessage() + "]\n\n");
            }

            csv.printf("%s,%s,%d,%d,%b,%b%n",
                    entry,
                    f.getName().replace(",", "_"),
                    f.getBody().getNumAddresses(),
                    f.getParameterCount(),
                    f.isThunk(),
                    decompiled);

            if ((total % 200) == 0) {
                println("Progress: " + total + " functions processed (" + ok + " decompiled)");
            }
        }

        cw.close();
        csv.close();
        ifc.dispose();

        println("DONE. Decompiled " + ok + "/" + total + " functions.");
        println("Output: " + cFile.getAbsolutePath());
        println("Index : " + csvFile.getAbsolutePath());
    }
}
